code.perFrame:
// basics
now=gettime(0) ; sec=now-last ; last=now ;
asp=h/w ; reg00=asp ; psize=h/280 ;
c=if(above(c,10),0,c+sec) ;
turn=if(equal(c,0),if(rand(50)%2,-turn,turn),turn) ;

// rotation
xturn=if(equal(c,0),if(rand(50)%2,-xturn,xturn),xturn) ;
yturn=if(equal(c,0),if(rand(50)%2,-yturn,yturn),yturn) ;
xg=xg*0.98+getspec(rand(31)*0.01,0.01,0)*xturn ;
yg=yg*0.98+getspec(rand(31)*0.01,0.01,0)*yturn ;
xr=xr+xg*sec ; yr=yr+yg*sec ;

sx=sin(xr) ; cx=cos(xr) ;
sy=sin(yr) ; cy=cos(yr) ;

// counters
bnd=0 ; specvol=n ; oscvol=n2 ;
rt=n3 ; zt=n4 ; st=n5 ; ct=n6 ;

// loopy loo
loop(n,
exec3(exec3(exec3(
assign(bnd,bnd+1),
assign(specvol,specvol+1),
assign(oscvol,oscvol+1)),
exec3(
assign(rt,rt+1),
assign(zt,zt+1),
assign(st,st+1)),
exec3(
assign(ct,ct+1),
assign(megabuf(specvol),megabuf(specvol)*0.975+getspec((bnd/n)*0.3+0.1,0,0)*turn),
assign(megabuf(oscvol),megabuf(oscvol)*0.975+abs(getosc(1-bnd/n,0,0))*0.5))),
exec3(
assign(megabuf(rt),megabuf(rt)+megabuf(specvol)*sec),
assign(megabuf(zt),0.3+megabuf(oscvol)*0.08),
assign(megabuf(st),sin(megabuf(rt))*megabuf(zt))),
assign(megabuf(ct),cos(megabuf(rt))*megabuf(zt)))) ;

code.perPoint:
p=(p+1)%n ;
x1=megabuf(p+n5+1) ;
